pub fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    assert!(
        s2.len() == n && s3.len() == n,
        "All input arrays must have the same length"
    );

    // Pre-allocate exactly 3n elements; guard against usize overflow.
    let cap = n.checked_mul(3).expect("Result length overflows usize");
    let mut res = Vec::with_capacity(cap);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}